<?php $title='Dashboard'; require __DIR__.'/partials/top.php'; $tid=(int)$_SESSION['user']['tenant_id'];$pdo=appDb();$channels=[];$recent=[];$days=array_fill(0,7,0);try{$q=$pdo->prepare('SELECT type,name,status FROM channels WHERE tenant_id=? ORDER BY id DESC');$q->execute([$tid]);$channels=$q->fetchAll();$q=$pdo->prepare("SELECT c.id,co.name client,ch.type,u.name agent FROM conversations c LEFT JOIN contacts co ON co.id=c.contact_id LEFT JOIN channels ch ON ch.id=c.channel_id LEFT JOIN users u ON u.id=c.assigned_user_id WHERE c.tenant_id=? AND c.status<>'closed' ORDER BY c.updated_at DESC LIMIT 10");$q->execute([$tid]);$recent=$q->fetchAll();$q=$pdo->prepare("SELECT DATE(created_at) d,COUNT(*) n FROM messages WHERE tenant_id=? AND created_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(created_at)");$q->execute([$tid]);$map=[];foreach($q->fetchAll() as $r)$map[$r['d']]=$r['n'];for($i=0;$i<7;$i++)$days[$i]=$map[date('Y-m-d',strtotime('-'.(6-$i).' days'))]??0;}catch(Throwable $e){}$max=max(1,...$days);$visible=['kpis','activity','channels','attention'];$legalTerms=[];try{$q=$pdo->prepare('SELECT widgets_json FROM dashboard_preferences WHERE user_id=?');$q->execute([$_SESSION['user']['id']]);$v=json_decode((string)$q->fetchColumn(),true);if(is_array($v))$visible=$v;if(isPlatformOwner()){$q=$pdo->query("SELECT title,content,version,published_at,updated_at FROM legal_documents WHERE document_key='terms_conditions' LIMIT 1");$legalTerms=$q->fetch()?:[];}}catch(Throwable $e){} ?>
<section class="welcome"><div><small>RESUMEN</small><h1>Hola, <?=htmlspecialchars(explode(' ',$_SESSION['user']['name'])[0])?></h1><p>Tu operación, organizada a tu manera.</p></div><button class="soft dashboard-customize"><i class="fa-solid fa-sliders"></i> Personalizar dashboard</button></section>
<section class="dashboard-widget <?=in_array('kpis',$visible)?'':'widget-hidden'?>" data-widget="kpis"><div class="premium-kpis"><article><b><?=count($channels)?></b><small>Canales configurados</small></article><article><b><?=count($recent)?></b><small>Conversaciones abiertas</small></article></div></section>
<section class="grid2 dashboard-grid"><article class="panel chart-card dashboard-widget <?=in_array('activity',$visible)?'':'widget-hidden'?>" data-widget="activity"><div class="panel-head"><div><b><i class="fa-solid fa-chart-column"></i> Actividad de mensajes</b><small>Últimos 7 días</small></div></div><div class="bars"><?php foreach($days as $i=>$n):?><div class="bar-wrap"><span class="bar-value"><?=$n?></span><div class="bar" style="height:<?=max(4,round($n/$max*100))?>%"></div><small><?=['L','M','X','J','V','S','D'][date('N',strtotime('-'.(6-$i).' days'))-1]?></small></div><?php endforeach?></div></article><article class="panel dashboard-widget <?=in_array('channels',$visible)?'':'widget-hidden'?>" data-widget="channels"><div class="panel-head"><div><b><i class="fa-solid fa-signal"></i> Canales</b><small>Estado real configurado</small></div></div><?php if(!$channels):?><div class="empty-compact"><i class="fa-solid fa-link-slash"></i><b>Sin canales configurados</b><a class="premium-link" href="?page=channels">Configurar canales <i class="fa-solid fa-arrow-right"></i></a></div><?php else:foreach($channels as $c):?><div class="source"><b><?=htmlspecialchars(ucfirst($c['type']).' · '.$c['name'])?></b><span class="status <?=$c['status']==='connected'?'ok':''?>"><?=htmlspecialchars($c['status'])?></span></div><?php endforeach;endif?></article></section>
<section class="panel dashboard-widget <?=in_array('attention',$visible)?'':'widget-hidden'?>" data-widget="attention"><div class="panel-head"><div><b>Conversaciones que requieren atención</b><small>Información real, sin datos de demostración</small></div><a class="premium-link" href="?page=inbox"><i class="fa-solid fa-inbox"></i> Abrir bandeja <i class="fa-solid fa-arrow-right"></i></a></div><div class="responsive-records"><?php if(!$recent):?><div class="empty-compact"><i class="fa-regular fa-comments"></i><b>No hay conversaciones pendientes</b><span>Cuando entren mensajes aparecerán aquí.</span></div><?php else:foreach($recent as $r):?><article class="record-card"><div><small>Cliente</small><b><?=htmlspecialchars($r['client']?:'Sin nombre')?></b></div><div><small>Canal</small><span><?=htmlspecialchars(ucfirst($r['type']))?></span></div><div><small>Asignado</small><span><?=htmlspecialchars($r['agent']?:'Sin asignar')?></span></div><a class="premium-link" href="?page=inbox&conversation=<?=$r['id']?>"><i class="fa-solid fa-eye"></i> Ver detalle</a></article><?php endforeach;endif?></div></section>
<?php if(isPlatformOwner()):?><section class="panel spaced legal-admin-panel"><div class="panel-head"><div><b><i class="fa-solid fa-file-signature"></i> Términos y Condiciones</b><small>Documento público utilizado durante el registro de nuevas empresas.</small></div><span class="legal-version-badge">Versión <?=htmlspecialchars((string)($legalTerms['version']??1))?></span></div><div class="legal-admin-summary"><div class="legal-admin-copy"><span class="legal-admin-icon"><i class="fa-solid fa-scale-balanced"></i></span><div><b><?=htmlspecialchars($legalTerms['title']??'Términos y Condiciones')?></b><p>Administra desde aquí el documento que los nuevos clientes deben revisar y aceptar antes de recibir su código de verificación.</p><small><i class="fa-regular fa-clock"></i> Última publicación: <?=!empty($legalTerms['published_at'])?htmlspecialchars(date('d/m/Y H:i',strtotime((string)$legalTerms['published_at']))):'Sin publicar'?></small></div></div><button type="button" class="primary" data-open="legalTermsAdminModal"><i class="fa-solid fa-pen-to-square"></i> Administrar términos</button></div></section><?php endif?>
<div class="modal-shell" id="dashboardModal"><div class="modal-card"><div class="modal-head"><div><b>Personalizar dashboard</b><small>La selección se guarda en tu cuenta y te acompaña en cualquier dispositivo.</small></div><button class="modal-close"><i class="fa-solid fa-xmark"></i></button></div><form id="dashboardPrefs"><div class="dashboard-choice-grid"><?php foreach(['kpis'=>'Indicadores principales','activity'=>'Actividad de mensajes','channels'=>'Estado de canales','attention'=>'Conversaciones por atender'] as $k=>$label):?><label class="premium-check"><input type="checkbox" name="widgets[]" value="<?=$k?>" <?=in_array($k,$visible)?'checked':''?>><span><i class="fa-solid fa-check"></i></span><b><?=$label?></b></label><?php endforeach?></div><div class="modal-actions"><button type="button" class="soft modal-close"><i class="fa-solid fa-xmark"></i> Cancelar</button><button class="primary"><i class="fa-solid fa-floppy-disk"></i> Guardar vista</button></div></form></div></div><?php if(isPlatformOwner()):?><div class="modal-shell" id="legalTermsAdminModal" aria-hidden="true"><div class="modal-card legal-admin-modal-card"><div class="modal-head"><div><b><i class="fa-solid fa-file-signature"></i> Administrar Términos y Condiciones</b><small>Al guardar se publica una nueva versión y será la que deberán aceptar los próximos registros.</small></div><button type="button" class="modal-close" aria-label="Cerrar"><i class="fa-solid fa-xmark"></i></button></div><form id="legalTermsForm" data-autofocus-form><input type="hidden" name="action" value="legal_terms_save"><div class="legal-editor-meta"><span><i class="fa-solid fa-code-branch"></i> Versión actual <b><?=htmlspecialchars((string)($legalTerms['version']??1))?></b></span><span><i class="fa-solid fa-calendar-check"></i> Publicado <?=!empty($legalTerms['published_at'])?htmlspecialchars(date('d/m/Y H:i',strtotime((string)$legalTerms['published_at']))):'sin fecha'?></span></div><div class="field"><label>Título del documento</label><input name="title" maxlength="190" required value="<?=htmlspecialchars($legalTerms['title']??'Términos y Condiciones')?>" placeholder="Términos y Condiciones"></div><div class="field"><label>Contenido</label><textarea name="content" class="legal-editor-textarea" required maxlength="50000" placeholder="Escribe aquí los términos que se mostrarán al usuario..."><?=htmlspecialchars($legalTerms['content']??'')?></textarea><small class="field-help">Puedes editar todo el documento. Para crear secciones usa títulos numerados como “1. Objeto” y deja una línea en blanco entre cada sección. El contenido se publica de forma segura, sin ejecutar HTML.</small></div><div class="legal-publish-note"><i class="fa-solid fa-circle-info"></i><div><b>Publicación versionada</b><span>Cada guardado incrementa automáticamente la versión. Los registros ya aceptados conservan la versión que aceptaron.</span></div></div><div class="modal-actions"><button type="button" class="soft modal-close"><i class="fa-solid fa-xmark"></i> Cancelar</button><button class="primary" type="submit"><i class="fa-solid fa-cloud-arrow-up"></i> Publicar nueva versión</button></div></form></div></div><?php endif?><?php require __DIR__.'/partials/bottom.php'; ?>
